  return [(r+m)*255,(g+m)*255,(b+m)*255]; }
const sm = x => x<=0?0:x>=1?1:x*x*(3-2*x);

const BW = Math.max(360, Math.min(700, Math.round(width/2.0)));
const BH = Math.max(120, Math.round(BW*height/width));
