  const g=createGraphics(BW,BH); g.pixelDensity(1); g.loadPixels();
  const H=P.hue;
  const deep=h2r(H,.84,.28), midc=h2r(H-4,.72,.50), cloth=h2r(H-8,.12,.90);
  const black=h2r(H,.55,.08), gold=h2r(44,.42,.86);
  const nB = Math.round(5 + P.density*16);
  const cen=[]; for(let i=0;i<nB;i++) cen.push([fr(i*3+1),fr(i*3+2),0.05+fr(i*3+3)*0.13*(1/P.scale)]);
  const sc = P.scale, bl = P.bleed;
  const freq = (8+P.density*22)/sc;
  for(let y=0;y<BH;y++){
    const vv=y/BH;
    for(let x=0;x<BW;x++){
      const uu=x/BW;
      let r=0;
      if(P.style==='arashi_pole'){
        const ang=0.6, dx=uu*Math.cos(ang)+vv*Math.sin(ang);
        const bow=0.06*Math.sin(vv*3.14159*2);
        r=Math.pow(0.5+0.5*Math.sin((dx+bow)*freq*3.14159),1.5);
        r=0.35*r + 0.65*Math.pow(0.5+0.5*Math.sin((dx)*freq*1.7*3.14159+1.3),2.0);
      } else if(P.style==='itajime_clamp'){
        const cellS=0.5/sc; let fx=((uu/cellS)%2); if(fx>1)fx=2-fx; let fy=((vv/cellS)%2); if(fy>1)fy=2-fy;
        const dd=Math.max(Math.abs(fx-0.5),Math.abs(fy-0.5))*2;
