      const idx=4*(y*BW+x);
      g.pixels[idx]=Math.max(0,Math.min(255,col[0]*gr));
      g.pixels[idx+1]=Math.max(0,Math.min(255,col[1]*gr));
      g.pixels[idx+2]=Math.max(0,Math.min(255,col[2]*gr));
